import json
from pathlib import Path
p=Path(__file__).parent;prior=p.parent/'integer-widening-sparse-owned-542a847'
read=lambda file:json.loads(file.read_text())
cache={}
def row(folder,corpus,id):
    key=(str(folder),corpus)
    if key not in cache:cache[key]={x['id']:x['actual'] for x in read(folder/f'after-{corpus}.json')['results']}
    return cache[key][id]
checks=read(prior/'extra-checks.json');preserved=0;changed=[]
for key,default in [('preserved_prior_checks',None),('preserved_same_stage_error_cause_differences',None),('wrapped_sort_type_errors','integral-types'),('preserved_non_float_control_errors','integral-types'),('new_error_causes','integral-widen')]:
    for entry in checks[key]:
        corpus=entry.get('corpus',default);id=entry['id']
        a,b=row(prior,corpus,id),row(p,corpus,id)
        if a.get('error')==b.get('error'):
            if key=='preserved_prior_checks' and ('candidate' in entry or 'zero' in id):assert a.get('rows')==b.get('rows'),id
            preserved+=1
        else:
            assert corpus in ['integral-types','integral-widen'],(corpus,id)
            assert entry['spark_condition']=='DIVIDE_BY_ZERO',(corpus,id)
            assert a['status']==b['status']=='execution_error'
            assert 'Divide by zero' in b['error'],(corpus,id,b)
            changed.append({'corpus':corpus,'id':id,'spark_condition':entry['spark_condition'],'before':a['error'],'after':b['error']})
new_spark={x['id']:x['actual'] for x in read(p/'spark.json')['results']}
new_candidate={x['id']:x['actual'] for x in read(p/'after-new.json')['results']}
causes=[];remaining=[]
for id,a in new_spark.items():
    b=new_candidate[id]
    if id in {f'{t}_empty_true' for t in ['tinyint','smallint','int','bigint']} or id=='control_bad_right_null_true':
        assert a['status']=='execution_error' and b['status']=='ok',(id,a,b)
        remaining.append({'id':id,'spark_condition':a['condition'],'candidate_status':b['status']})
        continue
    if a.get('condition')=='DIVIDE_BY_ZERO':
        assert b['status']=='execution_error' and 'Divide by zero' in b['error'],(id,a['status'],b)
        causes.append({'id':id,'spark_condition':a['condition'],'candidate_error':b['error']})
    if a['status']=='ok' and b['status']=='ok':
        assert b['types']==['Int64'],(id,b['types'])
        assert a['schema']['fields'][0]['type']=='long',(id,a['schema'])
result={'preserved_checks':preserved,'changed_error_messages_same_cause':changed,'new_zero_error_causes':causes,'new_corpus_remaining_differences':remaining,'known_same_stage_cause_gaps':checks['preserved_same_stage_error_cause_differences'],'wrapped_sort_type_errors':checks['wrapped_sort_type_errors']}
(p/'focused.json').write_text(json.dumps(result,indent=2)+'\n')
print('Preserved',preserved,'focused checks;',len(changed),'zero messages changed; verified',len(causes),'new zero error causes')

