import datetime, json, os, statistics, subprocess
from pathlib import Path
p=Path(__file__).parent;out=p/'performance';out.mkdir()
order=['before','after','after','before']*4
cases=['div_i8_column_ansitrue','div_i16_column_ansitrue','div_i32_column_ansitrue','div_column_ansitrue','div_i16_literal_ansitrue','div_i16_column_ansifalse','div_integer_ansitrue','plain_projection_ansitrue']
canonical={x['id']:x for x in json.loads((p/'after-subquery-check.json').read_text())['results']}
runs=[];base=os.environ.copy()
assert not any(k.startswith(('MALLOC_','GLIBC_','LD_PRELOAD','DECIMAL_BENCH_')) for k in base)
for index,variant in enumerate(order):
    shift=index%len(cases)
    for case in cases[shift:]+cases[:shift]:
        directory=out/f'{index:02}-{variant}-{case}';directory.mkdir()
        for name in ['control','ack']:os.mkfifo(directory/name)
        command=['perf','stat','--delay=-1',f'--control=fifo:{directory}/control,{directory}/ack','--json-output','-o',str(directory/'counters.jsonl'),'-e','{instructions:u,cycles:u},task-clock:u,context-switches:u,cpu-migrations:u,page-faults:u','--','taskset','-c','2',str(p/f'{variant}-bench'),str(directory/'capture.json'),'subqueries',case]
        env=base|{'DECIMAL_BENCH_RETAIN':'none','DECIMAL_BENCH_PERF_DIR':str(directory),'DECIMAL_BENCH_PERF_PHASE':'execution'}
        started=datetime.datetime.now(datetime.UTC).isoformat()
        result=subprocess.run(command,env=env,capture_output=True,text=True,check=True,timeout=120)
        capture=json.loads((directory/'capture.json').read_text());assert len(capture['results'])==1
        r=capture['results'][0]
        for field,value in canonical[case].items():
            if field not in ['logical_plan','physical_plan']:assert r[field]==value,(variant,case,field)
        assert r['retention']=='none' and r['retained_rows']==0
        counters=[json.loads(x) for x in (directory/'counters.jsonl').read_text().splitlines() if x.startswith('{')]
        assert len(counters)==6 and all(x['pcnt-running']==100 for x in counters)
        assert result.stderr.count('Events enabled')==1 and len(r['samples_ms'])==9
        runs.append({'variant':variant,'index':index,'case':case,'started_utc':started,'command':command,'capture':capture,'counters':counters,'median_ms':statistics.median(r['samples_ms'])})
    (p/'performance.json').write_text(json.dumps({'order':order,'cases':cases,'runs':runs},indent=2)+'\n')
    print(index,variant,'complete',flush=True)
summary={}
for case in cases:
    grouped={v:[r for r in runs if r['variant']==v and r['case']==case] for v in ['before','after']}
    stats={}
    for v,rows in grouped.items():
        medians=[r['median_ms'] for r in rows]
        instructions=[next(float(c['counter-value']) for c in r['counters'] if c['event']=='instructions:u') for r in rows]
        stats[v]={'processes':len(rows),'median_ms':statistics.median(medians),'process_medians_ms':medians,'median_instructions':statistics.median(instructions)}
    summary[case]=stats|{'latency_change_pct':100*(stats['after']['median_ms']/stats['before']['median_ms']-1),'instruction_change_pct':100*(stats['after']['median_instructions']/stats['before']['median_instructions']-1)}
    print(case,summary[case]['latency_change_pct'],summary[case]['instruction_change_pct'],flush=True)
(p/'performance-summary.json').write_text(json.dumps(summary,indent=2)+'\n')
